import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class TraceIds {
    static String requestId(String testName, long ts) {
        if (testName == null || testName.isBlank() || ts <= 0) {
            throw new IllegalArgumentException("invalid input");
        }
        String slug = testName.toLowerCase()
                .replaceAll("[^a-z0-9]+", "-")
                .replaceAll("^-+|-+$", "");
        if (slug.length() > 20) {
            slug = slug.substring(0, 20);
        }
        if (slug.isBlank()) {
            throw new IllegalArgumentException("invalid input");
        }
        return "qa-" + slug + "-" + ts;
    }
}

public class TraceIdsTest {
    @Test
    void normalizes() {
        assertEquals("qa-login-checkout-100", TraceIds.requestId("Login Checkout", 100L));
    }

    @Test
    void stripsNoise() {
        assertEquals("qa-order-pay-v2-42", TraceIds.requestId("Order@Pay v2!", 42L));
    }

    @Test
    void truncatesSlug() {
        String id = TraceIds.requestId("very long scenario name for tracing", 7L);
        String slug = id.substring(3, id.lastIndexOf('-'));
        assertTrue(slug.length() <= 20);
    }

    @Test
    void invalidName() {
        assertThrows(IllegalArgumentException.class, () -> TraceIds.requestId(" ", 1L));
    }
}
